<?php
 namespace Pterodactyl\Services\Dezerx; use Illuminate\Support\Str; use Pterodactyl\Models\Egg; use Pterodactyl\Models\Server; class StartupPresets { public const SETTING_KEY = 'startup'; private const LABEL_LIMIT = 60; private const DESCRIPTION_LIMIT = 200; private const COMMAND_LIMIT = 2000; public const MAX = 40; private const BUILT_IN = ['SERVER_MEMORY', 'SERVER_IP', 'SERVER_PORT']; private const DEFAULTS = [ [ 'label' => 'Aikar\'s flags', 'description' => 'The garbage collection tuning most Minecraft servers run. Suits a server under 12 GB. Heap is the whole allocation, which is what the egg\'s own 95 percent already works out to.', 'command' => 'java -Xms{{SERVER_MEMORY}}M -Xmx{{SERVER_MEMORY}}M -XX:+UseG1GC -XX:+ParallelRefProcEnabled -XX:MaxGCPauseMillis=200 -XX:+UnlockExperimentalVMOptions -XX:+DisableExplicitGC -XX:+AlwaysPreTouch -XX:G1NewSizePercent=30 -XX:G1MaxNewSizePercent=40 -XX:G1HeapRegionSize=8M -XX:G1ReservePercent=20 -XX:InitiatingHeapOccupancyPercent=15 -XX:G1HeapWastePercent=5 -XX:G1MixedGCCountTarget=4 -XX:G1MixedGCLiveThresholdPercent=90 -XX:G1RSetUpdatingPauseTimePercent=5 -XX:SurvivorRatio=32 -XX:+PerfDisableSharedMem -XX:MaxTenuringThreshold=1 -Dusing.aikars.flags=https://mcflags.emc.gs -Daikars.new.flags=true -jar {{SERVER_JARFILE}} --nogui', 'kind' => 'server', ], [ 'label' => 'Aikar\'s flags, 12 GB and up', 'description' => 'The same set with the larger heap regions Aikar publishes for 12 GB and more. Heap is the whole allocation, as above.', 'command' => 'java -Xms{{SERVER_MEMORY}}M -Xmx{{SERVER_MEMORY}}M -XX:+UseG1GC -XX:+ParallelRefProcEnabled -XX:MaxGCPauseMillis=200 -XX:+UnlockExperimentalVMOptions -XX:+DisableExplicitGC -XX:+AlwaysPreTouch -XX:G1NewSizePercent=40 -XX:G1MaxNewSizePercent=50 -XX:G1HeapRegionSize=16M -XX:G1ReservePercent=15 -XX:InitiatingHeapOccupancyPercent=20 -XX:G1HeapWastePercent=5 -XX:G1MixedGCCountTarget=4 -XX:G1MixedGCLiveThresholdPercent=90 -XX:G1RSetUpdatingPauseTimePercent=5 -XX:SurvivorRatio=32 -XX:+PerfDisableSharedMem -XX:MaxTenuringThreshold=1 -Dusing.aikars.flags=https://mcflags.emc.gs -Daikars.new.flags=true -jar {{SERVER_JARFILE}} --nogui', 'kind' => 'server', ], [ 'label' => 'The panel default', 'description' => 'What the egg ships with. A way back after trying one of the others.', 'command' => 'java -Xms128M -XX:MaxRAMPercentage=95.0 -Dterminal.jline=false -Dterminal.ansi=true -jar {{SERVER_JARFILE}}', 'kind' => 'server', ], [ 'label' => 'Crash diagnostics', 'description' => 'Writes a heap dump when the server runs out of memory and a rolling gc.log beside it. For finding a cause, not for every day.', 'command' => 'java -Xms128M -XX:MaxRAMPercentage=95.0 -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=heapdump.hprof -Xlog:gc*:file=gc.log:time,uptime:filecount=5,filesize=10M -jar {{SERVER_JARFILE}}', 'kind' => 'server', ], [ 'label' => 'Proxy flags', 'description' => 'Velocity\'s recommended flags, which BungeeCord and Waterfall take as well.', 'command' => 'java -Xms128M -XX:MaxRAMPercentage=95.0 -XX:+UseG1GC -XX:G1HeapRegionSize=4M -XX:+UnlockExperimentalVMOptions -XX:+ParallelRefProcEnabled -XX:+AlwaysPreTouch -XX:MaxInlineLevel=15 -jar {{SERVER_JARFILE}}', 'kind' => 'proxy', ], ]; public static function all(): array { $stored = Settings::get(self::SETTING_KEY) ?? []; $presets = []; foreach ((array) ($stored['presets'] ?? []) as $preset) { if (!is_array($preset)) { continue; } $id = (string) ($preset['id'] ?? ''); $command = self::clean((string) ($preset['command'] ?? ''), self::COMMAND_LIMIT); if ($id === '' || $command === '') { continue; } $presets[] = [ 'id' => $id, 'label' => self::clean((string) ($preset['label'] ?? ''), self::LABEL_LIMIT), 'description' => self::clean((string) ($preset['description'] ?? ''), self::DESCRIPTION_LIMIT), 'command' => $command, 'eggs' => array_values(array_filter( array_map('strval', (array) ($preset['eggs'] ?? [])), fn (string $uuid) => $uuid !== '', )), 'enabled' => (bool) ($preset['enabled'] ?? true), ]; } return $presets; } public static function find(string $id): ?array { foreach (self::all() as $preset) { if ($preset['id'] === $id) { return $preset; } } return null; } public static function forServer(Server $server): array { $uuid = $server->egg?->uuid; if ($uuid === null) { return []; } return array_values(array_filter( self::all(), fn (array $preset) => $preset['enabled'] && in_array($uuid, $preset['eggs'], true), )); } public static function store(array $input): bool { $presets = self::all(); if (count($presets) >= self::MAX) { return false; } $preset = self::shape($input, Str::lower(Str::random(10))); if ($preset === null) { return false; } $presets[] = $preset; self::put($presets); return true; } public static function seed(): array { $presets = self::all(); $taken = array_map(fn (array $preset) => mb_strtolower($preset['label']), $presets); $eggs = Egg::query()->with('variables')->get(); $counts = ['added' => 0, 'duplicate' => 0, 'unsuited' => 0, 'refused' => 0]; foreach (self::DEFAULTS as $definition) { if (in_array(mb_strtolower($definition['label']), $taken, true)) { ++$counts['duplicate']; continue; } $matched = $eggs ->filter(fn (Egg $egg) => self::suits($egg, $definition)) ->pluck('uuid') ->map('strval') ->values() ->all(); if ($matched === []) { ++$counts['unsuited']; continue; } if (count($presets) >= self::MAX) { ++$counts['refused']; continue; } $presets[] = [ 'id' => Str::lower(Str::random(10)), 'label' => $definition['label'], 'description' => $definition['description'], 'command' => $definition['command'], 'eggs' => $matched, 'enabled' => false, ]; ++$counts['added']; } if ($counts['added'] > 0) { self::put($presets); } return $counts; } private static function suits(Egg $egg, array $definition): bool { foreach (self::references($definition['command']) as $variable) { if (in_array($variable, self::BUILT_IN, true)) { continue; } if (!$egg->variables->contains('env_variable', $variable)) { return false; } } if (str_contains($definition['command'], '-jar') && str_contains((string) $egg->startup, 'unix_args')) { return false; } $proxy = preg_match('/bungee|waterfall|velocity|proxy/i', $egg->name) === 1; return $definition['kind'] === 'proxy' ? $proxy : !$proxy; } private static function references(string $command): array { preg_match_all('/{{\\s*([A-Za-z0-9_]+)\\s*}}/', $command, $matches); return array_values(array_unique($matches[1] ?? [])); } public static function update(string $id, array $input): void { $presets = []; foreach (self::all() as $preset) { if ($preset['id'] !== $id) { $presets[] = $preset; continue; } $presets[] = self::shape($input, $id) ?? $preset; } self::put($presets); } public static function delete(string $id): void { self::put(array_values(array_filter(self::all(), fn (array $preset) => $preset['id'] !== $id))); } private static function shape(array $input, string $id): ?array { $command = self::clean((string) ($input['command'] ?? ''), self::COMMAND_LIMIT); $label = self::clean((string) ($input['label'] ?? ''), self::LABEL_LIMIT); if ($command === '' || $label === '') { return null; } $eggs = array_map('strval', (array) ($input['eggs'] ?? [])); return [ 'id' => $id, 'label' => $label, 'description' => self::clean((string) ($input['description'] ?? ''), self::DESCRIPTION_LIMIT), 'command' => $command, 'eggs' => array_values(array_unique( Egg::query()->whereIn('uuid', $eggs)->pluck('uuid')->map('strval')->all(), )), 'enabled' => (bool) ($input['enabled'] ?? false), ]; } private static function put(array $presets): void { Settings::put(self::SETTING_KEY, ['presets' => array_values($presets)]); } private static function clean(string $value, int $limit): string { return mb_substr(trim(str_replace(["\r\n", "\r"], "\n", $value)), 0, $limit); } } 